NAME = "RSI band"
INPUTS = {"length": 14, "high": 70}
OUTPUTS = ["rsi", "over"]
PANE = "separate"

def update(ctx):
    rsi = ctx.indicator("rsi", length=int(ctx.params["length"]))
    if rsi is None:
        return None
    ctx.state["count"] = ctx.state.get("count", 0) + 1
    return {"rsi": rsi, "over": 1 if rsi > ctx.params["high"] else 0}
